const std = @import("std");
const tensor_mod = @import("../tensor/tensor.zig");
const dtype_mod = @import("../tensor/dtype.zig");
const config_mod = @import("../util/config.zig");
const kernels = @import("../kernels/efla_kernels.zig");
const memory = @import("../core/memory.zig");
const accel = @import("../hw/accel/accel_interface.zig");
const Thread = std.Thread;

pub const Tensor = tensor_mod.Tensor;
pub const Shape = tensor_mod.Shape;
pub const DType = dtype_mod.DType;

pub const EflaState = struct {
    state: *Tensor,
    num_heads: usize,
    batch_size: usize,
    state_dim: usize,
    value_dim: usize,
    allocator: std.mem.Allocator,
    device: tensor_mod.Device,
    device_id: i32,

    pub fn init(
        allocator: std.mem.Allocator,
        batch_size: usize,
        num_heads: usize,
        state_dim: usize,
        value_dim: usize,
        device: tensor_mod.Device,
        device_id: i32,
    ) !*EflaState {
        const self = try allocator.create(EflaState);
        errdefer allocator.destroy(self);

        var state_dims: [4]usize = .{ batch_size, num_heads, state_dim, value_dim };
        const state_shape = Shape.init(&state_dims);
        const state_tensor = try Tensor.zeros(allocator, state_shape, .fp32, device, device_id);
        errdefer state_tensor.deinit();

        self.* = .{
            .state = state_tensor,
            .num_heads = num_heads,
            .batch_size = batch_size,
            .state_dim = state_dim,
            .value_dim = value_dim,
            .allocator = allocator,
            .device = device,
            .device_id = device_id,
        };

        return self;
    }

    pub fn deinit(self: *EflaState) void {
        const a = self.allocator;
        self.state.deinit();
        a.destroy(self);
    }

    pub fn reset(self: *EflaState) !void {
        try self.state.zero_();
    }

    pub fn clone(self: *EflaState) !*EflaState {
        const new_tensor = try self.state.clone(self.allocator);
        errdefer new_tensor.deinit();

        const cloned = try self.allocator.create(EflaState);
        errdefer self.allocator.destroy(cloned);

        cloned.* = .{
            .state = new_tensor,
            .num_heads = self.num_heads,
            .batch_size = self.batch_size,
            .state_dim = self.state_dim,
            .value_dim = self.value_dim,
            .allocator = self.allocator,
            .device = self.device,
            .device_id = self.device_id,
        };

        return cloned;
    }
};

pub const EflaLayer = struct {
    config: config_mod.EflaConfig,
    hidden_dim: usize,
    num_heads: usize,
    head_dim: usize,
    w_k: *Tensor,
    w_v: *Tensor,
    w_q: *Tensor,
    w_o: *Tensor,
    beta_param: ?*Tensor,
    allocator: std.mem.Allocator,
    device: tensor_mod.Device,
    device_id: i32,

    pub fn init(
        allocator: std.mem.Allocator,
        config: config_mod.EflaConfig,
        hidden_dim: usize,
        num_heads: usize,
        head_dim: usize,
        device: tensor_mod.Device,
        device_id: i32,
        rng: *std.Random,
    ) !*EflaLayer {
        std.debug.assert(hidden_dim > 0);
        std.debug.assert(num_heads > 0);
        std.debug.assert(head_dim > 0);

        const self = try allocator.create(EflaLayer);
        errdefer allocator.destroy(self);

        const scale: f32 = @floatCast(@sqrt(2.0 / @as(f64, @floatFromInt(hidden_dim))));

        var w_k_dims: [2]usize = .{ hidden_dim, num_heads * head_dim };
        const w_k_shape = Shape.init(&w_k_dims);
        const w_k = try Tensor.randNormal(allocator, w_k_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_k.deinit();

        var w_v_dims: [2]usize = .{ hidden_dim, num_heads * head_dim };
        const w_v_shape = Shape.init(&w_v_dims);
        const w_v = try Tensor.randNormal(allocator, w_v_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_v.deinit();

        var w_q_dims: [2]usize = .{ hidden_dim, num_heads * head_dim };
        const w_q_shape = Shape.init(&w_q_dims);
        const w_q = try Tensor.randNormal(allocator, w_q_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_q.deinit();

        var w_o_dims: [2]usize = .{ num_heads * head_dim, hidden_dim };
        const w_o_shape = Shape.init(&w_o_dims);
        const w_o = try Tensor.randNormal(allocator, w_o_shape, .fp32, device, device_id, rng, 0.0, scale);
        errdefer w_o.deinit();

        var beta_param: ?*Tensor = null;
        if (config.learned_beta) {
            var beta_dims: [1]usize = .{1};
            const beta_shape = Shape.init(&beta_dims);
            const bp = try Tensor.full(allocator, beta_shape, .fp32, device, device_id, config.initial_beta);
            errdefer bp.deinit();
            beta_param = bp;
        }

        self.* = .{
            .config = config,
            .hidden_dim = hidden_dim,
            .num_heads = num_heads,
            .head_dim = head_dim,
            .w_k = w_k,
            .w_v = w_v,
            .w_q = w_q,
            .w_o = w_o,
            .beta_param = beta_param,
            .allocator = allocator,
            .device = device,
            .device_id = device_id,
        };

        return self;
    }

    pub fn deinit(self: *EflaLayer) void {
        const a = self.allocator;
        self.w_k.deinit();
        self.w_v.deinit();
        self.w_q.deinit();
        self.w_o.deinit();
        if (self.beta_param) |bp| bp.deinit();
        a.destroy(self);
    }

    pub fn getBeta(self: *EflaLayer) f32 {
        if (self.beta_param) |bp| {
            const ptr = bp.typedPtr(f32);
            if (ptr) |p| {
                return p[0];
            }
        }
        return self.config.initial_beta;
    }

    pub fn forward(
        self: *EflaLayer,
        input: *Tensor,
        state: ?*EflaState,
    ) !struct { output: *Tensor, new_state: *EflaState } {
        std.debug.assert(input.shape.ndim >= 3);
        std.debug.assert(input.shape.dim(2) == self.hidden_dim);

        const batch_size = input.shape.dim(0);
        const seq_len = input.shape.dim(1);

        const k = try matmul(self.allocator, input, self.w_k);
        defer k.deinit();

        const v = try matmul(self.allocator, input, self.w_v);
        defer v.deinit();

        const q = try matmul(self.allocator, input, self.w_q);
        defer q.deinit();

        var k_reshape_dims: [4]usize = .{ batch_size, seq_len, self.num_heads, self.head_dim };
        const k_reshaped = try k.reshape(Shape.init(&k_reshape_dims));
        defer k_reshaped.deinit();

        var v_reshape_dims: [4]usize = .{ batch_size, seq_len, self.num_heads, self.head_dim };
        const v_reshaped = try v.reshape(Shape.init(&v_reshape_dims));
        defer v_reshaped.deinit();

        var q_reshape_dims: [4]usize = .{ batch_size, seq_len, self.num_heads, self.head_dim };
        const q_reshaped = try q.reshape(Shape.init(&q_reshape_dims));
        defer q_reshaped.deinit();

        var current_state: *EflaState = undefined;
        var owns_state = false;
        if (state) |s| {
            std.debug.assert(s.batch_size == batch_size);
            std.debug.assert(s.num_heads == self.num_heads);
            std.debug.assert(s.state_dim == self.head_dim);
            std.debug.assert(s.value_dim == self.head_dim);
            current_state = try s.clone();
            owns_state = true;
        } else {
            current_state = try EflaState.init(
                self.allocator,
                batch_size,
                self.num_heads,
                self.head_dim,
                self.head_dim,
                self.device,
                self.device_id,
            );
            owns_state = true;
        }
        errdefer if (owns_state) current_state.deinit();

        const efla_output = try self.eflaForward(k_reshaped, v_reshaped, q_reshaped, current_state);
        defer efla_output.deinit();

        const projected = try matmul(self.allocator, efla_output, self.w_o);

        return .{ .output = projected, .new_state = current_state };
    }

    fn eflaForward(
        self: *EflaLayer,
        k: *Tensor,
        v: *Tensor,
        q: *Tensor,
        state: *EflaState,
    ) !*Tensor {
        const batch_size = k.shape.dim(0);
        const seq_len = k.shape.dim(1);

        var output_dims: [4]usize = .{ batch_size, seq_len, self.num_heads, self.head_dim };
        const output_shape = Shape.init(&output_dims);
        const output = try Tensor.zeros(self.allocator, output_shape, .fp32, self.device, self.device_id);
        errdefer output.deinit();

        const beta: f32 = self.getBeta();

        if (self.device == .cuda) {
            try kernels.eflaForwardCuda(
                k.ptr(),
                v.ptr(),
                q.ptr(),
                state.state.ptr(),
                output.ptr(),
                batch_size,
                seq_len,
                self.num_heads,
                self.head_dim,
                beta,
                self.config.chunk_size,
            );
        } else {
            try self.eflaForwardCpu(k, v, q, state, output, beta);
        }

        var reshaped_dims: [3]usize = .{ batch_size, seq_len, self.num_heads * self.head_dim };
        const reshaped = try output.reshape(Shape.init(&reshaped_dims));

        return reshaped;
    }

    fn eflaForwardCpu(
        self: *EflaLayer,
        k: *Tensor,
        v: *Tensor,
        q: *Tensor,
        state: *EflaState,
        output: *Tensor,
        beta: f32,
    ) !void {
        std.debug.assert(k.shape.ndim == 4);
        std.debug.assert(v.shape.ndim == 4);
        std.debug.assert(q.shape.ndim == 4);
        std.debug.assert(output.shape.ndim == 4);

        const batch_size = k.shape.dim(0);
        const seq_len = k.shape.dim(1);
        const d = self.head_dim;

        const k_ptr = k.typedPtr(f32) orelse return error.InvalidDType;
        const v_ptr = v.typedPtr(f32) orelse return error.InvalidDType;
        const q_ptr = q.typedPtr(f32) orelse return error.InvalidDType;
        const s_ptr = state.state.typedPtr(f32) orelse return error.InvalidDType;
        const o_ptr = output.typedPtr(f32) orelse return error.InvalidDType;

        const s_new_buf = try self.allocator.alloc(f32, d * d);
        defer self.allocator.free(s_new_buf);

        const kt_s_buf = try self.allocator.alloc(f32, d);
        defer self.allocator.free(kt_s_buf);

        for (0..batch_size) |b| {
            for (0..self.num_heads) |h| {
                const state_base = b * self.num_heads * d * d + h * d * d;

                for (0..seq_len) |t| {
                    const kv_base = b * seq_len * self.num_heads * d + t * self.num_heads * d + h * d;

                    var lambda: f32 = 0.0;
                    for (0..d) |dd| {
                        const k_val = k_ptr[kv_base + dd];
                        lambda += k_val * k_val;
                    }

                    const c_t: f32 = if (lambda < 1e-6) blk: {
                        const bl = beta * lambda;
                        var c: f32 = beta;
                        c -= 0.5 * beta * bl;
                        c += @as(f32, 1.0 / 6.0) * beta * beta * bl * lambda;
                        break :blk c;
                    } else blk: {
                        break :blk (1.0 - std.math.exp(-beta * lambda)) / lambda;
                    };

                    for (0..d) |j| {
                        var dot: f32 = 0.0;
                        for (0..d) |m| {
                            dot += k_ptr[kv_base + m] * s_ptr[state_base + m * d + j];
                        }
                        kt_s_buf[j] = dot;
                    }

                    const o_base = b * seq_len * self.num_heads * d + t * self.num_heads * d + h * d;

                    for (0..d) |d_out| {
                        var sum: f32 = 0.0;
                        for (0..d) |d_in| {
                            sum += s_ptr[state_base + d_in * d + d_out] * q_ptr[kv_base + d_in];
                        }
                        o_ptr[o_base + d_out] = sum;
                    }

                    for (0..d) |i| {
                        const k_i = k_ptr[kv_base + i];
                        for (0..d) |j| {
                            const s_old = s_ptr[state_base + i * d + j];
                            const v_j = v_ptr[kv_base + j];
                            s_new_buf[i * d + j] = s_old - c_t * k_i * kt_s_buf[j] + c_t * k_i * v_j;
                        }
                    }

                    for (0..d) |i| {
                        for (0..d) |j| {
                            s_ptr[state_base + i * d + j] = s_new_buf[i * d + j];
                        }
                    }
                }
            }
        }
    }

    pub fn backward(
        self: *EflaLayer,
        grad_output: *Tensor,
        input: *Tensor,
        state: *EflaState,
    ) !struct { grad_input: *Tensor, grad_state: *EflaState } {
        std.debug.assert(grad_output.shape.ndim >= 3);
        std.debug.assert(input.shape.ndim >= 3);

        const batch_size = input.shape.dim(0);
        const seq_len = input.shape.dim(1);

        _ = grad_output;
        _ = state;

        var grad_dims: [3]usize = .{ batch_size, seq_len, self.hidden_dim };
        const grad_input_shape = Shape.init(&grad_dims);
        const grad_input = try Tensor.zeros(self.allocator, grad_input_shape, .fp32, self.device, self.device_id);
        errdefer grad_input.deinit();

        const grad_state = try EflaState.init(
            self.allocator,
            batch_size,
            self.num_heads,
            self.head_dim,
            self.head_dim,
            self.device,
            self.device_id,
        );
        errdefer grad_state.deinit();

        return .{ .grad_input = grad_input, .grad_state = grad_state };
    }
};

fn matmul(allocator: std.mem.Allocator, a: *Tensor, b: *Tensor) !*Tensor {
    std.debug.assert(a.shape.ndim >= 2);
    std.debug.assert(b.shape.ndim >= 2);

    const a_ndim = a.shape.ndim;
    const b_ndim = b.shape.ndim;

    const M = a.shape.dim(a_ndim - 2);
    const K_a = a.shape.dim(a_ndim - 1);
    const K_b = b.shape.dim(b_ndim - 2);
    const N = b.shape.dim(b_ndim - 1);

    std.debug.assert(K_a == K_b);

    const K = K_a;

    var batch_size: usize = 1;
    if (a_ndim > 2) {
        var i: usize = 0;
        while (i < a_ndim - 2) : (i += 1) {
            batch_size *= a.shape.dim(i);
        }
    }

    const device = a.device;
    const device_id = a.device_id;

    if (a_ndim > 2) {
        var out_dims: [3]usize = .{ batch_size, M, N };
        const output_shape = Shape.init(&out_dims);
        const output = try Tensor.zeros(allocator, output_shape, .fp32, device, device_id);
        errdefer output.deinit();

        const a_ptr = a.typedPtr(f32) orelse return error.InvalidDType;
        const b_ptr = b.typedPtr(f32) orelse return error.InvalidDType;
        const o_ptr = output.typedPtr(f32) orelse return error.InvalidDType;

        for (0..batch_size) |bat| {
            const a_base = bat * M * K;
            const o_base = bat * M * N;
            for (0..M) |row| {
                for (0..N) |col| {
                    var sum: f32 = 0.0;
                    for (0..K) |kk| {
                        sum += a_ptr[a_base + row * K + kk] * b_ptr[kk * N + col];
                    }
                    o_ptr[o_base + row * N + col] = sum;
                }
            }
        }

        return output;
    } else {
        var out_dims: [2]usize = .{ M, N };
        const output_shape = Shape.init(&out_dims);
        const output = try Tensor.zeros(allocator, output_shape, .fp32, device, device_id);
        errdefer output.deinit();

        const a_ptr = a.typedPtr(f32) orelse return error.InvalidDType;
        const b_ptr = b.typedPtr(f32) orelse return error.InvalidDType;
        const o_ptr = output.typedPtr(f32) orelse return error.InvalidDType;

        for (0..M) |row| {
            for (0..N) |col| {
                var sum: f32 = 0.0;
                for (0..K) |kk| {
                    sum += a_ptr[row * K + kk] * b_ptr[kk * N + col];
                }
                o_ptr[row * N + col] = sum;
            }
        }

        return output;
    }
}

pub const ChunkedScan = struct {
    chunk_size: usize,
    num_chunks: usize,
    seq_len: usize,

    pub fn init(seq_len: usize, chunk_size: usize) ChunkedScan {
        std.debug.assert(chunk_size > 0);
        return .{
            .chunk_size = chunk_size,
            .num_chunks = (seq_len + chunk_size - 1) / chunk_size,
            .seq_len = seq_len,
        };
    }

    pub fn getChunkRange(self: ChunkedScan, chunk_idx: usize) struct { start: usize, end: usize } {
        std.debug.assert(chunk_idx < self.num_chunks);
        const start = chunk_idx * self.chunk_size;
        const end = @min(start + self.chunk_size, self.seq_len);
        return .{ .start = start, .end = end };
    }

    pub fn prefixScan(
        self: ChunkedScan,
        chunk_states: []*EflaState,
        allocator: std.mem.Allocator,
    ) !void {
        std.debug.assert(chunk_states.len == self.num_chunks);
        if (chunk_states.len <= 1) return;

        _ = allocator;

        var i: usize = 1;
        while (i < chunk_states.len) : (i += 1) {
            const prev = chunk_states[i - 1];
            const curr = chunk_states[i];

            const prev_ptr = prev.state.typedPtr(f32) orelse return error.InvalidDType;
            const curr_ptr = curr.state.typedPtr(f32) orelse return error.InvalidDType;

            const total = prev.batch_size * prev.num_heads * prev.state_dim * prev.value_dim;

            var j: usize = 0;
            while (j < total) : (j += 1) {
                curr_ptr[j] += prev_ptr[j];
            }
        }
    }
};

pub const RSFLayerConfig = struct {
    clip_min: f32 = -5.0,
    clip_max: f32 = 5.0,
    seed_offset: u64 = 0,
    grad_mean: bool = true,
};

fn checkedMul(a: usize, b: usize) !usize {
    return std.math.mul(usize, a, b) catch return error.Overflow;
}

fn checkedMulU64(a: u64, b: u64) !u64 {
    return std.math.mul(u64, a, b) catch return error.Overflow;
}

fn checkedAddU64(a: u64, b: u64) !u64 {
    return std.math.add(u64, a, b) catch return error.Overflow;
}

fn validateRSFTensor2D(t: *const tensor_mod.Tensor) !void {
    if (t.shape.dims.len != 2) return error.ShapeMismatch;
    const rows = t.shape.dims[0];
    const cols = t.shape.dims[1];
    const expected = try checkedMul(rows, cols);
    if (t.data.len != expected) return error.DataLengthMismatch;
}

fn countNonFinite(data: []const f32) usize {
    var count: usize = 0;
    for (data) |v| {
        if (!std.math.isFinite(v)) count += 1;
    }
    return count;
}

fn sanitizeSlice(data: []f32) void {
    for (data) |*v| {
        if (!std.math.isFinite(v.*)) v.* = 0.0;
    }
}

fn addBiasToSlice(data: []f32, bias: []const f32, batch_size: usize, dim: usize) !void {
    const required = try checkedMul(batch_size, dim);
    if (data.len < required) return error.DataLengthMismatch;
    if (bias.len < dim) return error.DataLengthMismatch;
    var offset: usize = 0;
    var b: usize = 0;
    while (b < batch_size) : (b += 1) {
        var d: usize = 0;
        while (d < dim) : (d += 1) {
            data[offset + d] += bias[d];
        }
        offset += dim;
    }
}

fn mulSliceInPlace(dst: []f32, src: []const f32) !void {
    if (dst.len != src.len) return error.DataLengthMismatch;
    var i: usize = 0;
    while (i < dst.len) : (i += 1) {
        dst[i] *= src[i];
    }
}

fn rsfTensorsOverlap(a: *const tensor_mod.Tensor, b: *const tensor_mod.Tensor) bool {
    if (a.data.len == 0 or b.data.len == 0) return false;
    const a_start = @intFromPtr(a.data.ptr);
    const a_end = a_start + a.data.len * @sizeOf(f32);
    const b_start = @intFromPtr(b.data.ptr);
    const b_end = b_start + b.data.len * @sizeOf(f32);
    return a_start < b_end and b_start < a_end;
}

pub const RSFLayer = struct {
    s_weight: tensor_mod.Tensor,
    t_weight: tensor_mod.Tensor,
    s_bias: tensor_mod.Tensor,
    t_bias: tensor_mod.Tensor,
    s_weight_grad: ?tensor_mod.Tensor,
    t_weight_grad: ?tensor_mod.Tensor,
    s_bias_grad: ?tensor_mod.Tensor,
    t_bias_grad: ?tensor_mod.Tensor,
    dim: usize,
    allocator: std.mem.Allocator,
    clip_min: f32,
    clip_max: f32,
    grad_mean: bool,
    deinitialized: bool,

    pub fn init(allocator: std.mem.Allocator, dim: usize) !RSFLayer {
        return initWithConfig(allocator, dim, .{});
    }

    pub fn initWithArena(arena: *memory.ArenaAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(arena.allocator(), dim, config);
    }

    pub fn initWithPool(pool: *memory.PoolAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(pool.allocator(), dim, config);
    }

    pub fn initWithSlab(slab: *memory.SlabAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(slab.allocator(), dim, config);
    }

    pub fn initWithBuddy(buddy: *memory.BuddyAllocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        return initWithConfig(buddy.allocator(), dim, config);
    }

    pub fn initWithConfig(allocator: std.mem.Allocator, dim: usize, config: RSFLayerConfig) !RSFLayer {
        if (dim == 0) return error.InvalidDimension;
        if (!std.math.isFinite(config.clip_min) or !std.math.isFinite(config.clip_max)) return error.NonFinite;
        if (!(config.clip_min < config.clip_max)) return error.InvalidConfig;
        if (config.clip_max > 20.0) return error.InvalidConfig;
        if (config.clip_min < -20.0) return error.InvalidConfig;

        _ = try checkedMul(dim, dim);

        const fan_in: f64 = @floatFromInt(dim);
        const fan_out: f64 = @floatFromInt(dim);
        const fan_sum = fan_in + fan_out;
        if (!(fan_sum > 0.0)) return error.InvalidDimension;

        const xavier_bound: f32 = @floatCast(@sqrt(6.0 / fan_sum));

        const weight_shape = [_]usize{ dim, dim };
        const bias_shape = [_]usize{ 1, dim };

        const seed1 = try checkedAddU64(42, config.seed_offset);
        const seed2 = try checkedAddU64(43, config.seed_offset);

        var s_w = try tensor_mod.Tensor.randomUniform(allocator, &weight_shape, -xavier_bound, xavier_bound, seed1);
        errdefer s_w.deinit();

        var t_w = try tensor_mod.Tensor.randomUniform(allocator, &weight_shape, -xavier_bound, xavier_bound, seed2);
        errdefer t_w.deinit();

        var s_b = try tensor_mod.Tensor.zeros(allocator, &bias_shape);
        errdefer s_b.deinit();

        var t_b = try tensor_mod.Tensor.zeros(allocator, &bias_shape);
        errdefer t_b.deinit();

        return RSFLayer{
            .s_weight = s_w,
            .t_weight = t_w,
            .s_bias = s_b,
            .t_bias = t_b,
            .s_weight_grad = null,
            .t_weight_grad = null,
            .s_bias_grad = null,
            .t_bias_grad = null,
            .dim = dim,
            .allocator = allocator,
            .clip_min = config.clip_min,
            .clip_max = config.clip_max,
            .grad_mean = config.grad_mean,
            .deinitialized = false,
        };
    }

    pub fn ensureGradients(self: *RSFLayer) !void {
        if (self.deinitialized) return error.NotInitialized;
        if (self.s_weight_grad != null) return;
        const weight_shape = [_]usize{ self.dim, self.dim };
        const bias_shape = [_]usize{ 1, self.dim };

        var swg = try tensor_mod.Tensor.zeros(self.allocator, &weight_shape);
        errdefer swg.deinit();
        var twg = try tensor_mod.Tensor.zeros(self.allocator, &weight_shape);
        errdefer twg.deinit();
        var sbg = try tensor_mod.Tensor.zeros(self.allocator, &bias_shape);
        errdefer sbg.deinit();
        var tbg = try tensor_mod.Tensor.zeros(self.allocator, &bias_shape);
        errdefer tbg.deinit();

        self.s_weight_grad = swg;
        self.t_weight_grad = twg;
        self.s_bias_grad = sbg;
        self.t_bias_grad = tbg;
    }

    pub fn deinit(self: *RSFLayer) void {
        if (self.deinitialized) return;
        self.s_weight.deinit();
        self.t_weight.deinit();
        self.s_bias.deinit();
        self.t_bias.deinit();
        if (self.s_weight_grad) |*g| g.deinit();
        if (self.t_weight_grad) |*g| g.deinit();
        if (self.s_bias_grad) |*g| g.deinit();
        if (self.t_bias_grad) |*g| g.deinit();
        self.s_weight_grad = null;
        self.t_weight_grad = null;
        self.s_bias_grad = null;
        self.t_bias_grad = null;
        self.deinitialized = true;
    }

    pub fn zeroGradients(self: *RSFLayer) void {
        if (self.deinitialized) return;
        if (self.s_weight_grad) |*g| for (g.data) |*v| {
            v.* = 0.0;
        };
        if (self.t_weight_grad) |*g| for (g.data) |*v| {
            v.* = 0.0;
        };
        if (self.s_bias_grad) |*g| for (g.data) |*v| {
            v.* = 0.0;
        };
        if (self.t_bias_grad) |*g| for (g.data) |*v| {
            v.* = 0.0;
        };
    }

    fn validatePair(self: *const RSFLayer, a: *const tensor_mod.Tensor, b: *const tensor_mod.Tensor) !usize {
        if (self.deinitialized) return error.NotInitialized;
        try validateRSFTensor2D(a);
        try validateRSFTensor2D(b);
        if (rsfTensorsOverlap(a, b)) return error.AliasedBuffers;
        if (a.shape.dims[1] != self.dim or b.shape.dims[1] != self.dim) return error.ShapeMismatch;
        if (a.shape.dims[0] != b.shape.dims[0]) return error.ShapeMismatch;
        if (self.s_bias.data.len != self.dim or self.t_bias.data.len != self.dim) return error.ShapeMismatch;
        const batch_size = a.shape.dims[0];
        if (batch_size == 0) return error.InvalidBatchSize;
        _ = try checkedMul(batch_size, self.dim);
        return batch_size;
    }

    fn computeScale(self: *const RSFLayer, x2_in: *const tensor_mod.Tensor, batch_size: usize) !tensor_mod.Tensor {
        var x2_copy = try x2_in.copy(self.allocator);
        defer x2_copy.deinit();
        var x2_t = try x2_copy.transpose(&.{ 1, 0 });
        defer x2_t.deinit();

        var s_w_copy = try self.s_weight.copy(self.allocator);
        defer s_w_copy.deinit();
        var s_x2_t = try s_w_copy.matmul(&x2_t, self.allocator);
        defer s_x2_t.deinit();

        var scale = try s_x2_t.transpose(&.{ 1, 0 });

        try addBiasToSlice(scale.data, self.s_bias.data, batch_size, self.dim);
        try scale.clip(self.clip_min, self.clip_max);
        try scale.exp();

        for (scale.data) |v| {
            if (v == 0.0 or !std.math.isFinite(v)) return error.NumericFailure;
        }

        return scale;
    }

    fn computeTranslation(self: *const RSFLayer, x1: *const tensor_mod.Tensor, batch_size: usize) !tensor_mod.Tensor {
        var x1_copy = try x1.copy(self.allocator);
        defer x1_copy.deinit();
        var x1_t = try x1_copy.transpose(&.{ 1, 0 });
        defer x1_t.deinit();

        var t_w_copy = try self.t_weight.copy(self.allocator);
        defer t_w_copy.deinit();
        var t_x1_t = try t_w_copy.matmul(&x1_t, self.allocator);
        defer t_x1_t.deinit();

        var trans = try t_x1_t.transpose(&.{ 1, 0 });

        try addBiasToSlice(trans.data, self.t_bias.data, batch_size, self.dim);

        for (trans.data) |v| {
            if (!std.math.isFinite(v)) return error.NumericFailure;
        }

        return trans;
    }

    pub fn rsfForward(self: *const RSFLayer, x1: *tensor_mod.Tensor, x2: *tensor_mod.Tensor) !void {
        const batch_size = try self.validatePair(x1, x2);

        var scale = try self.computeScale(x2, batch_size);
        defer scale.deinit();

        try mulSliceInPlace(x1.data, scale.data);

        if (countNonFinite(x1.data) > 0) return error.NumericFailure;

        var trans = try self.computeTranslation(x1, batch_size);
        defer trans.deinit();

        if (trans.data.len != x2.data.len) return error.ShapeMismatch;
        try x2.add(&trans);

        if (countNonFinite(x2.data) > 0) return error.NumericFailure;
    }

    pub fn inverse(self: *const RSFLayer, y1: *tensor_mod.Tensor, y2: *tensor_mod.Tensor) !void {
        const batch_size = try self.validatePair(y1, y2);

        var trans = try self.computeTranslation(y1, batch_size);
        defer trans.deinit();

        if (trans.data.len != y2.data.len) return error.ShapeMismatch;
        try y2.sub(&trans);

        if (countNonFinite(y2.data) > 0) return error.NumericFailure;

        var scale = try self.computeScale(y2, batch_size);
        defer scale.deinit();

        for (scale.data) |v| {
            if (v < 1e-30 or !std.math.isFinite(v)) return error.NumericFailure;
        }

        if (scale.data.len != y1.data.len) return error.ShapeMismatch;
        try y1.div(&scale);

        if (countNonFinite(y1.data) > 0) return error.NumericFailure;
    }

    pub fn rsfBackward(
        self: *RSFLayer,
        y1: *const tensor_mod.Tensor,
        y2: *const tensor_mod.Tensor,
        dy1_in: *const tensor_mod.Tensor,
        dy2_in: *const tensor_mod.Tensor,
        x1_out: *tensor_mod.Tensor,
        x2_out: *tensor_mod.Tensor,
        dx1_out: *tensor_mod.Tensor,
        dx2_out: *tensor_mod.Tensor,
    ) !void {
        const batch_size = try self.validatePair(y1, y2);
        _ = try self.validatePair(dy1_in, dy2_in);

        try validateRSFTensor2D(x1_out);
        try validateRSFTensor2D(x2_out);
        try validateRSFTensor2D(dx1_out);
        try validateRSFTensor2D(dx2_out);

        const bd = try checkedMul(batch_size, self.dim);

        if (x1_out.shape.dims[0] != batch_size or x2_out.shape.dims[0] != batch_size) return error.ShapeMismatch;
        if (dx1_out.shape.dims[0] != batch_size or dx2_out.shape.dims[0] != batch_size) return error.ShapeMismatch;
        if (x1_out.shape.dims[1] != self.dim or x2_out.shape.dims[1] != self.dim) return error.ShapeMismatch;
        if (dx1_out.shape.dims[1] != self.dim or dx2_out.shape.dims[1] != self.dim) return error.ShapeMismatch;
        if (x1_out.data.len != bd or x2_out.data.len != bd) return error.DataLengthMismatch;
        if (dx1_out.data.len != bd or dx2_out.data.len != bd) return error.DataLengthMismatch;

        try self.ensureGradients();

        var dy1 = try dy1_in.copy(self.allocator);
        defer dy1.deinit();

        var dy2 = try dy2_in.copy(self.allocator);
        defer dy2.deinit();

        if (countNonFinite(dy1.data) > 0) return error.NumericFailure;
        if (countNonFinite(dy2.data) > 0) return error.NumericFailure;

        var trans = try self.computeTranslation(y1, batch_size);
        defer trans.deinit();

        var x2 = try y2.copy(self.allocator);
        defer x2.deinit();
        try x2.sub(&trans);

        if (countNonFinite(x2.data) > 0) return error.NumericFailure;

        var dy2_t = try dy2.transpose(&.{ 1, 0 });
        defer dy2_t.deinit();

        var y1_copy_for_matmul = try y1.copy(self.allocator);
        defer y1_copy_for_matmul.deinit();
        var dt = try dy2_t.matmul(&y1_copy_for_matmul, self.allocator);
        defer dt.deinit();

        const grad_scale: f32 = if (self.grad_mean) blk: {
            const bs_f = @as(f32, @floatFromInt(batch_size));
            if (bs_f == 0.0) break :blk 1.0;
            const gs = 1.0 / bs_f;
            if (!std.math.isFinite(gs)) break :blk 1.0;
            break :blk gs;
        } else 1.0;

        if (self.t_weight_grad) |*twg| {
            if (dt.data.len != twg.data.len) return error.DataLengthMismatch;
            var i: usize = 0;
            while (i < dt.data.len) : (i += 1) {
                const val = dt.data[i] * grad_scale;
                if (std.math.isFinite(val)) {
                    twg.data[i] += val;
                }
            }
        }

        if (self.t_bias_grad) |*tbg| {
            if (tbg.data.len != self.dim) return error.DataLengthMismatch;
            var b: usize = 0;
            var offset: usize = 0;
            while (b < batch_size) : (b += 1) {
                var d: usize = 0;
                while (d < self.dim) : (d += 1) {
                    const val = dy2.data[offset + d] * grad_scale;
                    if (std.math.isFinite(val)) {
                        tbg.data[d] += val;
                    }
                }
                offset += self.dim;
            }
        }

        var t_weight_copy = try self.t_weight.copy(self.allocator);
        defer t_weight_copy.deinit();
        var t_weight_t = try t_weight_copy.transpose(&.{ 1, 0 });
        defer t_weight_t.deinit();

        var grad_from_t_t = try t_weight_t.matmul(&dy2_t, self.allocator);
        defer grad_from_t_t.deinit();

        var grad_from_t = try grad_from_t_t.transpose(&.{ 1, 0 });
        defer grad_from_t.deinit();

        if (grad_from_t.data.len != dy1.data.len) return error.DataLengthMismatch;
        try dy1.add(&grad_from_t);
        sanitizeSlice(dy1.data);

        var x2_t = try x2.transpose(&.{ 1, 0 });
        defer x2_t.deinit();

        var s_weight_copy = try self.s_weight.copy(self.allocator);
        defer s_weight_copy.deinit();
        var s_pre_t = try s_weight_copy.matmul(&x2_t, self.allocator);
        defer s_pre_t.deinit();

        var s_pre = try s_pre_t.transpose(&.{ 1, 0 });
        defer s_pre.deinit();

        try addBiasToSlice(s_pre.data, self.s_bias.data, batch_size, self.dim);

        var exp_s = try s_pre.copy(self.allocator);
        defer exp_s.deinit();
        try exp_s.clip(self.clip_min, self.clip_max);
        try exp_s.exp();

        for (exp_s.data) |v| {
            if (v == 0.0 or !std.math.isFinite(v)) return error.NumericFailure;
        }

        var x1 = try y1.copy(self.allocator);
        defer x1.deinit();
        try x1.div(&exp_s);

        if (countNonFinite(x1.data) > 0) return error.NumericFailure;

        @memcpy(x1_out.data, x1.data);
        @memcpy(x2_out.data, x2.data);

        if (exp_s.data.len != dy1.data.len) return error.DataLengthMismatch;
        var i: usize = 0;
        while (i < bd) : (i += 1) {
            dx1_out.data[i] = dy1.data[i] * exp_s.data[i];
        }

        var ds = try tensor_mod.Tensor.init(self.allocator, &.{ batch_size, self.dim });
        defer ds.deinit();
        i = 0;
        while (i < bd) : (i += 1) {
            const s_val = s_pre.data[i];
            if (!std.math.isFinite(s_val) or s_val < self.clip_min or s_val > self.clip_max) {
                ds.data[i] = 0.0;
                continue;
            }
            const dscale_val = dy1.data[i] * x1.data[i];
            const ds_val = dscale_val * exp_s.data[i];
            if (!std.math.isFinite(ds_val)) {
                ds.data[i] = 0.0;
            } else {
                ds.data[i] = ds_val;
            }
        }

        var ds_t = try ds.transpose(&.{ 1, 0 });
        defer ds_t.deinit();

        var ds_w = try ds_t.matmul(&x2, self.allocator);
        defer ds_w.deinit();

        if (self.s_weight_grad) |*swg| {
            if (ds_w.data.len != swg.data.len) return error.DataLengthMismatch;
            i = 0;
            while (i < ds_w.data.len) : (i += 1) {
                const val = ds_w.data[i] * grad_scale;
                if (std.math.isFinite(val)) {
                    swg.data[i] += val;
                }
            }
        }

        if (self.s_bias_grad) |*sbg| {
            if (sbg.data.len != self.dim) return error.DataLengthMismatch;
            var b: usize = 0;
            var offset: usize = 0;
            while (b < batch_size) : (b += 1) {
                var d: usize = 0;
                while (d < self.dim) : (d += 1) {
                    const val = ds.data[offset + d] * grad_scale;
                    if (std.math.isFinite(val)) {
                        sbg.data[d] += val;
                    }
                }
                offset += self.dim;
            }
        }

        var s_weight_copy2 = try self.s_weight.copy(self.allocator);
        defer s_weight_copy2.deinit();
        var s_weight_t = try s_weight_copy2.transpose(&.{ 1, 0 });
        defer s_weight_t.deinit();

        var grad_from_s_t = try s_weight_t.matmul(&ds_t, self.allocator);
        defer grad_from_s_t.deinit();

        var grad_from_s = try grad_from_s_t.transpose(&.{ 1, 0 });
        defer grad_from_s.deinit();

        if (grad_from_s.data.len != dy2.data.len) return error.DataLengthMismatch;
        i = 0;
        while (i < bd) : (i += 1) {
            dx2_out.data[i] = dy2.data[i] + grad_from_s.data[i];
        }

        if (countNonFinite(dx1_out.data) > 0) return error.NumericFailure;
        if (countNonFinite(dx2_out.data) > 0) return error.NumericFailure;
    }
};

pub const RSFConfig = struct {
    clip_min: f32 = -5.0,
    clip_max: f32 = 5.0,
    grad_mean: bool = true,
    max_dim: usize = 1 << 20,
    max_layers: usize = 1 << 20,
};

const SAVE_VERSION: u32 = 3;

const ControlBlock = struct {
    freed: std.atomic.Value(u8),
    allocator: std.mem.Allocator,
    dim: usize,
    num_layers: usize,
    layers: []RSFLayer,
    cfg: RSFConfig,
    gpu_accel: ?accel.RSFAccelerator,
    gpu_available: std.atomic.Value(u8),
    gpu_weight_version: u64,
    cpu_weight_version: u64,
    mutex: Thread.Mutex,
    f16_buf: ?[]f16,
};

pub const RSF = struct {
    ctrl: ?*ControlBlock,

    pub fn init(allocator: std.mem.Allocator, dim: usize, num_layers: usize) !RSF {
        return initWithConfig(allocator, dim, num_layers, .{});
    }

    pub fn initWithConfig(allocator: std.mem.Allocator, dim: usize, num_layers: usize, cfg: RSFConfig) !RSF {
        if (dim == 0) return error.InvalidDimension;
        if (num_layers == 0) return error.InvalidLayerCount;
        if (dim > cfg.max_dim or num_layers > cfg.max_layers) return error.TooLarge;
        if (!std.math.isFinite(cfg.clip_min) or !std.math.isFinite(cfg.clip_max)) return error.NonFinite;
        if (!(cfg.clip_min < cfg.clip_max)) return error.InvalidConfig;

        const dim_sq = try checkedMul(dim, dim);
        _ = try checkedMul(dim, 2);

        var ctrl = try allocator.create(ControlBlock);
        errdefer allocator.destroy(ctrl);

        ctrl.* = .{
            .freed = std.atomic.Value(u8).init(0),
            .allocator = allocator,
            .dim = dim,
            .num_layers = num_layers,
            .layers = try allocator.alloc(RSFLayer, num_layers),
            .cfg = cfg,
            .gpu_accel = null,
            .gpu_available = std.atomic.Value(u8).init(0),
            .gpu_weight_version = 0,
            .cpu_weight_version = 1,
            .mutex = Thread.Mutex{},
            .f16_buf = null,
        };
        errdefer allocator.free(ctrl.layers);

        var initialized_count: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < initialized_count) : (j += 1) {
                ctrl.layers[j].deinit();
            }
        }

        var l: usize = 0;
        while (l < num_layers) : (l += 1) {
            const seed_base = try checkedMulU64(@as(u64, @intCast(l)), 10007);
            const layer_cfg = RSFLayerConfig{
                .clip_min = cfg.clip_min,
                .clip_max = cfg.clip_max,
                .seed_offset = seed_base,
                .grad_mean = cfg.grad_mean,
            };
            ctrl.layers[l] = try RSFLayer.initWithConfig(allocator, dim, layer_cfg);
            initialized_count += 1;
        }

        if (accel.RSFAccelerator.init(dim)) |gpu| {
            ctrl.gpu_accel = gpu;
            ctrl.gpu_available.store(1, .seq_cst);
            ctrl.gpu_weight_version = 0;
            ctrl.f16_buf = allocator.alloc(f16, dim_sq) catch null;
        } else |_| {}

        var rsf = RSF{ .ctrl
